import { randomBytes } from 'node:crypto'

/**
 * Canonical identity (E0.1 R1 §2): "server-generated UUIDv7 stored as immutable strings; external/source
 * IDs remain separate."
 *
 * Payload's own row `id` (idType `uuid`, generated by Postgres) stays the storage key. `canonical_id` is the
 * Revenue Engine identity: generated here, on the server, on create only, and never writable afterwards
 * (see `guards.ts`). A Typeform `event_id` or response `token` is a source identity and is stored in its own
 * field; it never becomes a canonical id.
 */

const UUID_V7 = /^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/

/** RFC 9562 UUIDv7: 48-bit Unix ms timestamp, version 7, variant 10, 74 random bits. */
export function uuidv7(now: number = Date.now()): string {
  if (!Number.isInteger(now) || now < 0 || now > 0xffffffffffff)
    throw new Error('uuidv7: timestamp out of range')
  const bytes = randomBytes(16)
  let ts = now
  for (let i = 5; i >= 0; i--) {
    bytes[i] = ts & 0xff
    ts = Math.floor(ts / 256)
  }
  bytes[6] = (bytes[6]! & 0x0f) | 0x70
  bytes[8] = (bytes[8]! & 0x3f) | 0x80
  const hex = bytes.toString('hex')
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`
}

export const isUuidV7 = (value: unknown): value is string => typeof value === 'string' && UUID_V7.test(value)

/** Milliseconds encoded in a UUIDv7 (used only by tests and diagnostics). */
export const uuidv7Timestamp = (id: string): number => parseInt(id.replace(/-/g, '').slice(0, 12), 16)

const CROCKFORD = '0123456789ABCDEFGHJKMNPQRSTVWXYZ'

/**
 * `rfq_number` — the stable human reference quoted to a customer (E1.1 `{{rfq_reference}}`).
 *
 * Format `RFQ-YYYYMMDD-XXXXXXXX`: the UTC receipt date plus 40 random bits taken from the canonical UUIDv7
 * (Crockford base32, no I/L/O/U ambiguity). It is derived **once**, at creation, from server values only;
 * a client can never supply it, and `guards.ts` refuses any later change. Uniqueness is enforced by a
 * unique index, not assumed from randomness. The exact public numbering format is an owner input; this
 * format is stable, collision-checked and replaceable only by a *new* field, never by rewriting old numbers.
 */
export function rfqNumberFor(canonicalId: string, receivedAt: Date): string {
  if (!isUuidV7(canonicalId)) throw new Error('rfqNumberFor: canonical id must be a UUIDv7')
  if (Number.isNaN(receivedAt.getTime())) throw new Error('rfqNumberFor: invalid receipt time')
  const random = canonicalId.replace(/-/g, '').slice(-10) // 40 bits of the random tail
  let n = BigInt(`0x${random}`)
  let code = ''
  for (let i = 0; i < 8; i++) {
    code = CROCKFORD[Number(n & 31n)]! + code
    n >>= 5n
  }
  const d = receivedAt.toISOString().slice(0, 10).replace(/-/g, '')
  return `RFQ-${d}-${code}`
}

export const RFQ_NUMBER_PATTERN = /^RFQ-\d{8}-[0-9A-HJKMNP-TV-Z]{8}$/
